"""Pack the GPT Image edited QQ/H1 raster for the launcher and native UI."""
import hashlib,json
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[2];ASSETS=ROOT/'h1-qq-native/app/assets'
source=ASSETS/'qq-h1-gpt.png';im=Image.open(source).convert('RGBA')
# Normalize transparent padding during sprite packing, preserving the edited art.
bounds=im.getchannel('A').point(lambda a:255 if a>32 else 0).getbbox()
assert bounds and im.getchannel('A').getextrema()==(0,255)
im=im.crop(bounds);im.thumbnail((128,128),Image.Resampling.LANCZOS)
packed=Image.new('RGBA',(128,128));packed.alpha_composite(im,((128-im.width)//2,(128-im.height)//2));packed.save(ASSETS/'qq.png');im=packed
png=(ASSETS/'qq.png').read_bytes();lines=['/* Generated by tools/build_ui_assets.py from assets/qq-h1-gpt.png. */','#ifndef H1QQ_ICON_H','#define H1QQ_ICON_H']
for size in (16,24,56):
    scaled=im.resize((size,size),Image.Resampling.LANCZOS);values=[(a<<24)|(r<<16)|(g<<8)|b for r,g,b,a in scaled.get_flattened_data()]
    lines.append(f'static const uint32_t qq_icon_{size}[{size*size}]={{')
    lines.extend(','.join(f'0x{v:08x}u' for v in values[i:i+12])+',' for i in range(0,len(values),12));lines.append('};')
lines.append('#endif');(ASSETS/'qq_icon.h').write_text('\n'.join(lines)+'\n',encoding='utf-8',newline='\n')
(ASSETS/'manifest.json').write_text(json.dumps({'renderer':'built-in GPT Image edit; Pillow sprite packing','source_file':source.name,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'official_reference_url':'https://static-res.qq.com/static-res/imqq/qq-logo.png','official_reference_page':'https://im.qq.com/index','prompt_file':'qq-image-prompt.txt','prompt_sha256':hashlib.sha256((ASSETS/'qq-image-prompt.txt').read_bytes()).hexdigest(),'packed_alpha_bounds':bounds,'png_sha256':hashlib.sha256(png).hexdigest(),'header_sha256':hashlib.sha256((ASSETS/'qq_icon.h').read_bytes()).hexdigest()},indent=2)+'\n',encoding='utf-8',newline='\n')
print('Packed GPT Image QQ icon: desktop PNG and 16/24/56 pixel application sprites')
